class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        bits = [1 if ch == '1' else 0 for ch in s]
        INF = 10 ** 9

        def can(L: int) -> bool:
            dp = [[INF] * (L + 1) for _ in range(2)]

            for c in (0, 1):
                r = 1
                flips = 0 if c == bits[0] else 1
                dp[c][r] = min(dp[c][r], flips)

            for i in range(1, n):
                ndp = [[INF] * (L + 1) for _ in range(2)]
                for b in (0, 1):
                    for r in range(1, L + 1):
                        cur = dp[b][r]
                        if cur == INF:
                            continue
                        for c in (0, 1):
                            if c == b and r == L:
                                continue
                            nr = r + 1 if c == b else 1
                            flips = 0 if c == bits[i] else 1
                            if cur + flips < ndp[c][nr]:
                                ndp[c][nr] = cur + flips
                dp = ndp

            ans = INF
            for b in (0, 1):
                for r in range(1, L + 1):
                    ans = min(ans, dp[b][r])
            return ans <= numOps

        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if can(mid):
                high = mid
            else:
                low = mid + 1
        return low
```

