from typing import List

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        arr = nums[:]
        ops = 0

        while True:
            sorted_flag = True
            for i in range(1, len(arr)):
                if arr[i] < arr[i - 1]:
                    sorted_flag = False
                    break

            if sorted_flag:
                return ops

            best_idx = 0
            best_sum = arr[0] + arr[1]

            for i in range(1, len(arr) - 1):
                cur_sum = arr[i] + arr[i + 1]
                if cur_sum < best_sum:
                    best_sum = cur_sum
                    best_idx = i

            arr = arr[:best_idx] + [arr[best_idx] + arr[best_idx + 1]] + arr[best_idx + 2:]
            ops += 1
